package com.retail.inventory.service;
import com.retail.inventory.dto.request.*; import com.retail.inventory.entity.*; import com.retail.inventory.exception.*; import com.retail.inventory.repository.*; import com.retail.inventory.service.impl.InventoryServiceImpl; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)
class InventoryServiceImplTest {
 @Mock InventoryRepository inventoryRepository; @Mock ProductRepository productRepository; @Mock WarehouseRepository warehouseRepository; @Mock StockTransactionRepository transactionRepository; @Mock StockTransferRepository transferRepository; @Mock StockAlertRepository alertRepository; @InjectMocks InventoryServiceImpl service;
 @Test void adjustmentRejectsNegativeStock(){ Inventory i=inventory(5,0); when(inventoryRepository.findByProductIdAndWarehouseIdForUpdate(1L,1L)).thenReturn(Optional.of(i)); assertThrows(InsufficientStockException.class,()->service.adjust(StockAdjustmentRequest.builder().productId(1L).warehouseId(1L).quantityChange(-6).reason("count").build())); verify(transactionRepository,never()).save(any()); }
 @Test void transferRejectsInsufficientAvailableStock(){ Inventory i=inventory(5,2); when(inventoryRepository.findByProductIdAndWarehouseIdForUpdate(1L,1L)).thenReturn(Optional.of(i)); assertThrows(InsufficientStockException.class,()->service.transfer(StockTransferRequest.builder().productId(1L).fromWarehouseId(1L).toWarehouseId(2L).quantity(4).build())); verify(transferRepository,never()).save(any()); }
 @Test void transferRejectsSameWarehouse(){ assertThrows(BadRequestException.class,()->service.transfer(StockTransferRequest.builder().productId(1L).fromWarehouseId(1L).toWarehouseId(1L).quantity(1).build())); }
 private Inventory inventory(int onHand,int reserved){ Product p=new Product();p.setId(1L);p.setReorderPoint(2);Warehouse w=new Warehouse();w.setId(1L);Inventory i=new Inventory();i.setProduct(p);i.setWarehouse(w);i.setQuantityOnHand(onHand);i.setQuantityReserved(reserved);return i; }
}
